using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using SerialMonitor.Core.Automation;
using SerialMonitor.Core.Protocols;
using SerialMonitor.WinUI.Models;
using SerialMonitor.WinUI.Services;

static class MstpUartCheck
{
    static readonly JsonSerializerOptions Json=new() {WriteIndented=true};
    sealed record Case(string Name,byte[] Tx,byte[] Rx,int HeaderErrors=0,int DataErrors=0);
    // PC oracle uses a generated byte table, independently of MCU's bit loop.
    static int Step(int crc,int polynomial,int mask)
    { for(int i=0;i<8;i++) crc=(crc>>1)^((crc&1)!=0?polynomial:0); return crc&mask; }
    static readonly byte[] HeaderTable=Enumerable.Range(0,256).Select(i=>(byte)Step(i,0x81,255)).ToArray();
    static readonly ushort[] DataTable=Enumerable.Range(0,256).Select(i=>(ushort)Step(i,0x8408,65535)).ToArray();
    internal static byte[] Frame(byte type,byte destination,byte source,byte[] payload)
    {
        byte[] header=[type,destination,source,(byte)(payload.Length>>8),(byte)payload.Length];
        int hc=255;foreach(byte b in header) hc=HeaderTable[hc^b];
        int dc=65535;foreach(byte b in payload) dc=(dc>>8)^DataTable[(dc^b)&255];dc^=65535;
        return [0x55,0xFF,..header,(byte)(hc^255),..payload,..payload.Length>0?new[]{(byte)dc,(byte)(dc>>8)}:Array.Empty<byte>()];
    }
    static Case Make(string name,byte[] payload,int h=0,int d=0)
    {
        var rx=Frame(4,2,1,payload);if(h>0)rx[7]^=1;if(d>0)rx[^1]^=1;
        return new(name,Frame(3,1,2,payload),rx,h,d);
    }
    static readonly Case[] Cases=[Make("NORMAL","ABC"u8.ToArray()),Make("HEADER_CRC","CRCH"u8.ToArray(),h:1),
        Make("DATA_CRC","CRCD"u8.ToArray(),d:1),Make("RECOVERY","ABC"u8.ToArray()),
        Make("MAX",Enumerable.Range(0,501).Select(i=>(byte)i).ToArray()),Make("EMPTY",[])];
    static void Require(bool test,string message) {if(!test)throw new InvalidOperationException(message);}
    static void Assert(Case item,byte[] raw,ProtocolAnalysisSnapshot s)
    {
        Require(raw.AsSpan().SequenceEqual(item.Rx),item.Name+" UART/C bytes mismatch: "+Convert.ToHexString(raw));
        int errors=item.HeaderErrors+item.DataErrors;var a=s.Statistics;
        Require(s.LastError is null && s.TotalFrames==1 && a.Rx==1 && a.Tx==0 && a.CrcValid==1-errors && a.CrcErrors==errors &&
            a.HeaderCrcErrors==item.HeaderErrors && a.DataCrcErrors==item.DataErrors && a.Incomplete==0 && a.Undecoded==0 &&
            s.DroppedChunks==0 && s.DroppedBytes==0,item.Name+" analysis counters: "+JsonSerializer.Serialize(s));
    }
    public static async Task Run(string[] args)
    {
        using var stop=new CancellationTokenSource(TimeSpan.FromMinutes(2));
        if(args is ["mstp-offline",var directory])
        {
            for(int i=0;i<Cases.Length;i++)
            {
                var raw=File.ReadAllBytes(Path.Combine(directory,$"mstp-{i}.bin"));
                await using var analyzer=new BacnetMstpAnalyzer();analyzer.SetEnabled(true);
                analyzer.TryEnqueue(raw,ProtocolDirection.Rx,1,DateTimeOffset.Now);await Task.Delay(150,stop.Token);
                Assert(Cases[i],raw,analyzer.Snapshot());Console.WriteLine("PASS native C + independent PC oracle + app analyzer: "+Cases[i].Name);
            }
            string folder=Path.GetFullPath(Path.Combine(directory,"..","sequences","mstp"));
            var gui=await new CommandSequenceFileService().LoadAsync(Directory.GetFiles(folder,"*.gui.json"),stop.Token);
            Require(gui.Count==1 && gui[0].Steps.Count==8,"MS/TP GUI RX Check definition");
            using var cli=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"01-mstp-cases.cli.json")));
            var definition=AutomationSequenceValidation.Parse(cli.RootElement);Require(definition.Steps.Count==4,"MS/TP CLI definition");
            await using var combined=new BacnetMstpAnalyzer();combined.SetEnabled(true);
            for(int i=0;i<4;i++)
            {
                Require(gui[0].Steps[2*i].CommandText.Replace(" ","")==Convert.ToHexString(Cases[i].Tx),"GUI request bytes");
                Require(gui[0].Steps[2*i+1].CommandText.Replace(" ","")==Convert.ToHexString(Cases[i].Rx),"GUI response bytes");
                combined.TryEnqueue(Cases[i].Tx,ProtocolDirection.Tx,1,DateTimeOffset.Now,new(Stopwatch.GetTimestamp(),true,40,1.75));
                combined.TryEnqueue(Cases[i].Rx,ProtocolDirection.Rx,1,DateTimeOffset.Now,new(Stopwatch.GetTimestamp(),true,40,1.75));
            }
            await Task.Delay(150,stop.Token);var summary=combined.Snapshot();var a=summary.Statistics;
            Require(summary.TotalFrames==8 && a.Tx==4 && a.Rx==4 && a.CrcValid==6 && a.CrcErrors==2 && a.HeaderCrcErrors==1 &&
                a.DataCrcErrors==1 && a.Incomplete==0 && summary.DroppedBytes==0,"Combined sequence counter contract");
            Console.WriteLine("PASS GUI/CLI sequence imports, exact bytes, TX4/RX4/CRC valid6/errors2/header1/data1");return;
        }
        if(args is not ["mstp-live",_,_,_])throw new ArgumentException("mstp-offline BUILD_DIR | mstp-live PORT MANIFEST NEW_EVIDENCE_DIR");
        string port=args[1],evidence=Path.GetFullPath(args[3]);Require(!Directory.Exists(evidence),"Use a new evidence directory");Directory.CreateDirectory(evidence);
        using var manifest=JsonDocument.Parse(File.ReadAllText(args[2]));string build=manifest.RootElement.GetProperty("buildId").GetString()!;
        string version=manifest.RootElement.GetProperty("firmwareVersion").GetString()!;
        await using var serial=new SerialService();var gate=new object();List<byte[]>? active=null;int retained=0;bool overflow=false;
        BacnetMstpAnalyzer? analysis=null;var errors=new System.Collections.Concurrent.ConcurrentQueue<string>();
        serial.Error+=(_,error)=>errors.Enqueue(error);
        serial.CaptureBytesReceived+=(session,chunk)=> {
            lock(gate) {
                if(active is null)return;
                if(active.Count>=4096 || chunk.Bytes.Length>65536-retained){overflow=true;return;}
                active.Add(chunk.Bytes);retained+=chunk.Bytes.Length;
                analysis?.TryEnqueue(chunk.Bytes,ProtocolDirection.Rx,session,DateTimeOffset.Now,
                    new(chunk.ReceivedTimestamp,chunk.EndsAtNativeIdleBoundary,serial.AppliedReceiveIdleTimeoutMs,1.75));
            }
        };
        await serial.ConnectAsync(new SerialSettings {PortName=port,BaudRate=115200},new SerialReceiveOptions {UseNativeIdleTimeout=true,IdleTimeoutMs=40},stop.Token);
        var drain=Task.Run(async()=>{await foreach(var _ in serial.ReceivedBytes.ReadAllAsync(stop.Token)){}},stop.Token);
        var results=new List<object>();
        async Task<byte[]> Request(string name,byte[] tx,BacnetMstpAnalyzer? analyzer=null)
        {
            lock(gate){active=[];analysis=analyzer;retained=0;overflow=false;}
            await serial.SendBytesAsync(tx,Convert.ToHexString(tx),stop.Token);await Task.Delay(650,stop.Token);
            byte[] rx;lock(gate){rx=active!.SelectMany(c=>c).ToArray();active=null;analysis=null;}
            File.WriteAllBytes(Path.Combine(evidence,name+".tx.bin"),tx);File.WriteAllBytes(Path.Combine(evidence,name+".rx.bin"),rx);
            Require(!overflow && errors.IsEmpty,"Transport capture gap/error");return rx;
        }
        async Task Text(string name,string command,string expected)
        {Require(Encoding.ASCII.GetString(await Request(name,Encoding.ASCII.GetBytes(command+"\r\n")))==expected,name+" identity/mode mismatch");}
        try
        {
            await Task.Delay(600,stop.Token); // Drain possible pre-flash VCP bytes, no TX.
            await Text("ID","ID?","ID NUCLEO-F103RB STM32F103RB SERIAL-LAB/1\r\n");
            await Text("BUILD","BUILD?",$"BUILD version={version} protocol=1 id={build}\r\n");await Text("RTU","RTU","OK RTU\r\n");
            foreach(var item in Cases)
            {
                await using var analyzer=new BacnetMstpAnalyzer();analyzer.SetEnabled(true);
                byte[] raw=await Request(item.Name,item.Tx,analyzer);await Task.Delay(100,stop.Token);
                var snapshot=analyzer.Snapshot();Assert(item,raw,snapshot);
                results.Add(new {item.Name,bytes=raw.Length,snapshot.Statistics,snapshot.DroppedChunks,snapshot.DroppedBytes});
                Console.WriteLine($"PASS UART MS/TP {item.Name}: {raw.Length} bytes, header errors {snapshot.Statistics.HeaderCrcErrors}, data errors {snapshot.Statistics.DataCrcErrors}");
            }
            var bad=(byte[])Cases[0].Tx.Clone();bad[^1]^=1;
            Require((await Request("BAD_REQUEST",bad)).Length==0,"Bad request CRC must be silent");
            Require((await Request("AFTER_BAD_REQUEST",Cases[0].Tx)).AsSpan().SequenceEqual(Cases[0].Rx),"Recovery after bad request CRC");
            byte[] modbus=Convert.FromHexString("010300000002C40B");
            Require((await Request("MODBUS",modbus)).AsSpan().SequenceEqual(Convert.FromHexString("01030400FA0064DBE9")),"Existing Modbus response changed");
            Require((await Request("AFTER_MODBUS",Cases[0].Tx)).AsSpan().SequenceEqual(Cases[0].Rx),"MS/TP after Modbus");
            await Text("LAB","LAB","OK LAB\r\n");byte[] status=await Request("STATUS",Encoding.ASCII.GetBytes("STATUS?\r\n"));
            Require(Encoding.ASCII.GetString(status).Contains("rx_drops=0 uart_errors=0 tx_rejected=0",StringComparison.Ordinal),"MCU transport errors");
            await Text("RTU_FINAL","RTU","OK RTU\r\n");
            File.WriteAllText(Path.Combine(evidence,"report.json"),JsonSerializer.Serialize(new {passed=true,port,baud=115200,serialFormat="8N1",byteTimeoutMs=40,build,version,
                firmwareSha256=manifest.RootElement.GetProperty("sha256").GetString(),hardwareVerified=true,
                analyzerSha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(BacnetMstpAnalyzer).Assembly.Location))),
                scope="Real UART, app SerialService RX chunk analysis, independent oracle; isolated Test Request/Response bench; no GUI rendering or RS485 token network test",results},Json));
        }
        catch(Exception ex){File.WriteAllText(Path.Combine(evidence,"failure.json"),JsonSerializer.Serialize(new {passed=false,error=ex.ToString(),results},Json));throw;}
        finally {lock(gate){active=null;analysis=null;}await serial.DisconnectAsync(CancellationToken.None);await drain.WaitAsync(TimeSpan.FromSeconds(5));}
    }
}
